frappe.ui.form.on('Gate Entry', {
    purchase_order(frm) {
        if (!frm.doc.purchase_order) {
            frm.clear_table("items");
            frm.set_value("supplier", "");
            frm.set_value("supplier_name", "");
            frm.refresh_field("items");
            return;
        }

        frappe.db.get_doc("Purchase Order", frm.doc.purchase_order).then(po => {

            // Supplier auto fill
            frm.set_value("supplier", po.supplier);

            // Supplier Name auto fill
            frm.set_value("supplier_name", po.supplier_name);

            // Clear old rows
            frm.clear_table("items");

            // PO items auto fill
            if (po.items && po.items.length > 0) {
                po.items.forEach(d => {
                    let row = frm.add_child("items");

                    row.item = d.item_code;
                    row.item_name = d.item_name;
                    row.qty = d.qty;
                    row.uom = d.uom;
                    row.rate = d.rate;
                    row.remarks = d.description;
                });
            }

            frm.refresh_field("items");
        });
    }
});

