function set_po_naming_series(frm) {
    if (!frm.is_new()) return;

    if (!frm.doc.custom_purchase_order_type || !frm.doc.unit) return;

    let po_code = frm.doc.custom_purchase_order_type.split("-")[0].trim();

    let unit_map = {
        "Unit-1": "U1",
        "Unit-2": "U2",
        "Unit-6": "U6"
    };

    let digit_map = {
        "CDRM": "1",
        "CDEM": "2",
        "CIRM": "3",
        "CIEM": "4",
        "CCM": "5",
        "CCS": "6",
        "CWO": "7",
        "CJW": "8",
        "CSTO": "9"
    };

    let unit_code = unit_map[frm.doc.unit];
    let digit = digit_map[po_code];

    if (!unit_code || !digit) return;

    let date = frm.doc.transaction_date ? new Date(frm.doc.transaction_date) : new Date();
    let year = date.getFullYear();

    let fy = `${year}-${String(year + 1).slice(-2)}`;

    let series = `${po_code}/${unit_code}/${digit}.####./${fy}`;

    frm.set_value("naming_series", series);
}

